; map.asm -- chapter 11: A < E, unsigned and signed, as two pictures
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "map.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
MAPU    EQU $C200               ; the unsigned picture; the signed one 512 bytes on
blk_src EQU VARS + $10          ; showblk's working bytes, in the RAM
blk_rc  EQU VARS + $12
blk_k   EQU VARS + $14
blk_w   EQU VARS + $15
blk_h   EQU VARS + $16
; A < E drawn for A = 0, 4 ... 252 across and E = 0, 4 ... 252 down:
; a pixel wherever the answer is yes. On the left the carry after CP
; answers, the numbers taken as unsigned; on the right slt answers, the
; numbers taken as signed (figure 11.1).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 2
        ld c, 2
        ld hl, m0
        call puts
        ld b, 2
        ld c, 18
        ld hl, m1
        call puts
        ld hl, MAPU             ; HL: a line of the unsigned picture
        ld e, 0                 ; E: the second number
mline:  push hl
        call uline              ; the line of the unsigned picture
        pop hl
        push hl
        inc h
        inc h                   ; the same line, 512 bytes on
        call sline              ; the line of the signed picture
        pop hl
        ld bc, 8
        add hl, bc              ; the next line
        ld a, e
        add a, 4
        ld e, a                 ; the next second number
        jr nc, mline            ; until E goes round past 252
        ld hl, MAPU + 0
        ld de, $0808            ; 8 bytes across, 8 rows of cells
        ld a, 128
        ld b, 4
        ld c, 2
        call showblk            ; the picture, as 64 characters
        ld hl, MAPU + 512
        ld de, $0808            ; 8 bytes across, 8 rows of cells
        ld a, 192
        ld b, 4
        ld c, 18
        call showblk            ; the picture, as 64 characters
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; uline: 8 bytes from HL for the second number E: a pixel for each first
;        number D = 0, 4 ... 252 below E, taken as unsigned
uline:  ld d, 0
ul1:    ld b, 8                 ; eight pixels to a byte
ul2:    ld a, d
        cp e                    ; the carry: D < E
        rl c                    ; the answer into C
        inc d
        inc d
        inc d
        inc d
        djnz ul2
        ld (hl), c
        inc hl
        ld a, d
        or a
        jr nz, ul1              ; until D goes round to 0
        ret

; sline: the same, with the numbers taken as signed
sline:  ld d, 0
sl1:    ld b, 8
sl2:    ld a, d
        call slt                ; the carry: D < E, signed
        rl c
        inc d
        inc d
        inc d
        inc d
        djnz sl2
        ld (hl), c
        inc hl
        ld a, d
        or a
        jr nz, sl1
        ret

; slt: the carry set if A < E, both taken as signed (-128 to 127). Uses A.
;      CP subtracts; without overflow S is the answer, and with overflow
;      it is upside down.
slt:    cp e                    ; A - E
        jp po, slt1             ; no overflow: S tells
        jp m, no                ; overflow, S = 1: A is not less
yes:    scf
        ret
slt1:   jp m, yes               ; no overflow, S = 1: A is less
no:     or a                    ; the carry clear
        ret

; showblk: a bitmap in the RAM or the ROM, W bytes across and 8 x H lines
;          down, line after line, sent to the VDP as W x H character shapes
;          from code A, and those characters put on the screen in a block
;          whose top left is row B, column C. HL = the bitmap, D = W, E = H.
;          The display must be off (chapter 20).
showblk:
        ld (blk_src), hl
        ld (blk_rc), bc
        ld (blk_k), a
        ld a, d
        ld (blk_w), a
        ld a, e
        ld (blk_h), a
        ld a, (blk_k)
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; the shape of character K is at K x 8
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, (blk_w)
        ld e, a
        ld d, 0                 ; DE: W, from one line to the next
        ld hl, (blk_src)
        ld a, (blk_h)
        ld b, a                 ; B: the rows of cells left
sb1:    push bc
        push hl                 ; HL: the top line of this row of cells
        ld a, (blk_w)
        ld c, a                 ; C: the cells left in the row
sb2:    push hl
        ld b, 8
sb3:    ld a, (hl)              ; the cell's eight lines, a byte each
        out (VDP_DATA), a
        add hl, de              ; one line down
        djnz sb3
        pop hl
        inc hl                  ; the next cell: one byte across
        dec c
        jr nz, sb2
        pop hl
        ld b, 8
sb4:    add hl, de
        djnz sb4                ; eight lines down: the next row of cells
        pop bc
        djnz sb1
        ld bc, (blk_rc)
        ld a, (blk_k)
        ld d, a                 ; D: the next code
        ld a, (blk_h)
        ld e, a                 ; E: the rows left
sn1:    call at                 ; the name of (B, C)
        ld a, (blk_w)
        ld h, a
sn2:    ld a, d
        out (VDP_DATA), a
        inc d
        dec h
        jr nz, sn2
        inc b
        dec e
        jr nz, sn1
        ret
m0:     db "UNSIGNED: C", 0
m1:     db "SIGNED: S, P/V", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
